let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrorCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)$"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(line.startIndex..., in: line)
    guard let match = regex.firstMatch(in: line, range: range) else { continue }

    let hour = Int(String(line[Range(match.range(at: 2), in: line)!]))!
    let level = String(line[Range(match.range(at: 3), in: line)!])
    let component = String(line[Range(match.range(at: 4), in: line)!])
    let message = String(line[Range(match.range(at: 5), in: line)!])

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        componentErrorCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")
let topComponent = componentErrorCounts.max { $0.value < $1.value }!
print("Component with Most Errors: \(topComponent.key) (\(topComponent.value) errors)")
print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")
let topHour = hourCounts.max { $0.value < $1.value }!
print("Busiest Hour: \(String(format: "%02d:00", topHour.key)) (\(topHour.value) entries)")

