import Foundation

let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = lines.dropFirst()

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    if fields.count >= 6 {
        let name = fields[1].trimmingCharacters(in: .whitespaces)
        let department = fields[2].trimmingCharacters(in: .whitespaces)
        let salary = Double(fields[3].trimmingCharacters(in: .whitespaces)) ?? 0
        employees.append(Employee(name: name, department: department, salary: salary))
    }
}

func formatInt(_ number: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 0
    return formatter.string(from: NSNumber(value: number)) ?? "\(number)"
}

func formatDecimal(_ number: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.minimumFractionDigits = 2
    formatter.maximumFractionDigits = 2
    return formatter.string(from: NSNumber(value: number)) ?? String(format: "%.2f", number)
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

