print("Departments with >2 employees:")
for (dept, count) in deptsWithMoreThan2 {
    print("  \(dept) (\(count) employees)")
}
print("")

let totalBudget = employees.reduce(0) { $0 + $1.salary }
print("Total Budget: $\(formatInt(Int(totalBudget)))")

