import * as fs from 'fs';

const csvPath = '<tmp>';
const content = fs.readFileSync(csvPath, 'utf-8');
const lines = content.trim().split('\n');

interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const employees: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',').map(c => c.trim());
  if (cols.length < 6) continue;
  employees.push({
    employee_id: cols[0],
    name: cols[1],
    department: cols[2],
    salary: parseFloat(cols[3]),
    start_date: cols[4],
    rating: cols[5],
  });
}

function formatNumber(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const [intPart, decPart] = fixed.split('.');
  const sign = intPart.startsWith('-') ? '-' : '';
  const digits = sign ? intPart.substring(1) : intPart;
  const withCommas = digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  let result = sign + withCommas;
  if (decimals > 0 && decPart !== undefined) {
    result += '.' + decPart;
  }
  return result;
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) {
    deptSalaries.set(emp.department, []);
  }
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptSalaries.keys()).sort();

let highestPaid = employees[0];
for (const emp of employees) {
  if (emp.salary > highestPaid.salary) {
    highestPaid = emp;
  }
}

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
  deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}

const deptsWithMoreThan2 = Array.from(deptCounts.entries())
  .filter(([, count]) => count > 2)
  .sort(([a], [b]) => a.localeCompare(b));

const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

const out: string[] = [];
out.push('=== Salary Report ===');
out.push('');
out.push('Average Salary by Department:');
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  out.push(`  ${dept}: $${formatNumber(avg, 2)}`);
}
out.push('');
out.push(`Highest Paid: ${highestPaid.name} ($${formatNumber(highestPaid.salary, 0)})`);
out.push('');
out.push('Departments with >2 employees:');
for (const [dept, count] of deptsWithMoreThan2) {
  out.push(`  ${dept} (${count} employees)`);
}
out.push('');
out.push(`Total Budget: $${formatNumber(totalBudget, 0)}`);

process.stdout.write(out.join('\n') + '\n');

