use std::collections::BTreeMap;
use std::fs;

fn format_int_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_avg_commas(avg: f64) -> String {
    let cents = (avg * 100.0).round() as i64;
    let int_part = cents / 100;
    let dec_part = cents % 100;
    format!("${}.{:02}", format_int_commas(int_part as u64), dec_part)
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: BTreeMap<String, Vec<u64>> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: u64 = 0;
    let mut total_budget: u64 = 0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: u64 = fields[3].trim().parse().expect("Failed to parse salary");

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary;
    }

    print!("=== Salary Report ===\n");
    print!("\n");
    print!("Average Salary by Department:\n");
    for (dept, salaries) in &dept_salaries {
        let avg: f64 = salaries.iter().map(|s| *s as f64).sum::<f64>() / salaries.len() as f64;
        print!("  {}: {}\n", dept, format_avg_commas(avg));
    }
    print!("\n");
    print!("Highest Paid: {} (${})\n", highest_paid_name, format_int_commas(highest_paid_salary));
    print!("\n");
    print!("Departments with >2 employees:\n");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            print!("  {} ({} employees)\n", dept, salaries.len());
        }
    }
    print!("\n");
    print!("Total Budget: ${}\n", format_int_commas(total_budget));
}

