use std::fs;
use std::collections::BTreeMap;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: BTreeMap<String, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let bracket_end = line.find(']').expect("Missing ] in line");
        let timestamp = &line[1..bracket_end]; // YYYY-MM-DD HH:MM:SS

        // After "] "
        let after_bracket = &line[bracket_end + 2..];

        // Level is the next word
        let level_end = after_bracket.find(' ').expect("Missing space after level");
        let level = &after_bracket[..level_end];

        // After level+space, expect "(component) - message"
        let after_level = &after_bracket[level_end + 1..];
        let paren_start = after_level.find('(').expect("Missing ( in line");
        let paren_end = after_level.find(')').expect("Missing ) in line");
        let component = &after_level[paren_start + 1..paren_end];

        // After ") - message"
        let after_paren = &after_level[paren_end + 1..];
        let message = after_paren
            .strip_prefix(" - ")
            .unwrap_or(after_paren)
            .to_string();

        // Count by level
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // Count errors by component and collect error messages
        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message);
        }

        // Count by hour (timestamp is "YYYY-MM-DD HH:MM:SS", hour at index 11..13)
        let hour = &timestamp[11..13];
        let hour_key = format!("{}:00", hour);
        *hour_counts.entry(hour_key).or_insert(0) += 1;
    }

    // Output
    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = component_errors
        .iter()
        .max_by_key(|(_, c)| *c)
        .expect("No errors found");
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs = error_messages;
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in &unique_msgs {
