#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char *name;
    char *dept;
    double salary;
} Emp;

typedef struct {
    char *name;
    double sum;
    long count;
} Dept;

static char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (!p) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    memcpy(p, s, n);
    return p;
}

static void format_commas(long long v, char *out)
{
    char tmp[32];
    int n = snprintf(tmp, sizeof tmp, "%lld", v);
    int op = 0, i;
    for (i = 0; i < n; i++) {
        if (i > 0 && (n - i) % 3 == 0)
            out[op++] = ',';
        out[op++] = tmp[i];
    }
    out[op] = '\0';
}

static void format_avg(double avg, char *out)
{
    long long cents = (long long)llround(avg * 100.0);
    long long dollars = cents / 100;
    int frac = (int)(cents % 100);
    char intpart[32];
    format_commas(dollars, intpart);
    snprintf(out, 256, "%s.%02d", intpart, frac);
}

static int cmp_dept(const void *a, const void *b)
{
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

int main(void)
{
    const char *path =
        "<tmp>";

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "cannot open %s\n", path);
        return 1;
    }

    Emp *emps = NULL;
    size_t nemp = 0, capemp = 0;
    Dept *depts = NULL;
    size_t ndepts = 0, capdepts = 0;

    double total = 0.0;
    char *highest_name = NULL;
    double highest_sal = -1.0;

    char *line = NULL;
    size_t linecap = 0;
    ssize_t len;
    int first = 1;

    while ((len = getline(&line, &linecap, fp)) != -1) {
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len == 0)
            continue;
        if (first) {
            first = 0;
            continue;
        }

        /* split: employee_id, name, department, salary, ... */
        char *p = line;
        char *f0 = p;
        char *c1 = strchr(p, ',');
        if (!c1) continue;
        *c1 = '\0';
        p = c1 + 1;
        char *f1 = p;
        char *c2 = strchr(p, ',');
        if (!c2) continue;
        *c2 = '\0';
        p = c2 + 1;
        char *f2 = p;
        char *c3 = strchr(p, ',');
        if (!c3) continue;
        *c3 = '\0';
        p = c3 + 1;
        char *f3 = p;
        char *c4 = strchr(p, ',');
        if (c4)
            *c4 = '\0';

        (void)f0;

        char *f_name = f1;
        char *f_dept = f2;
        char *f_sal = f3;

        double sal = strtod(f_sal, NULL);

