                    return 1;
                }
            }
            d = &depts[ndepts++];
            d->name = xstrdup(f_dept);
            d->sum = 0.0;
            d->count = 0;
        }
        d->sum += sal;
        d->count++;
        total += sal;

        if (sal > highest_sal) {
            highest_sal = sal;
            if (highest_name)
                free(highest_name);
            highest_name = xstrdup(f_name);
        }

        /* keep employee record (dynamic array) */
        if (nemp == capemp) {
            capemp = capemp ? capemp * 2 : 16;
            emps = realloc(emps, capemp * sizeof *emps);
            if (!emps) {
                fprintf(stderr, "out of memory\n");
                return 1;
            }
        }
        emps[nemp].name = xstrdup(f_name);
        emps[nemp].dept = xstrdup(f_dept);
        emps[nemp].salary = sal;
        nemp++;
    }

