        format_avg(avg, buf);
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    if (highest_name) {
        format_commas((long long)llround(highest_sal), buf);
        printf("Highest Paid: %s ($%s)\n", highest_name, buf);
    } else {
        printf("Highest Paid: N/A ($0)\n");
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (size_t i = 0; i < ndepts; i++) {
        if (depts[i].count > 2)
            printf("  %s (%ld employees)\n", depts[i].name, depts[i].count);
    }
    printf("\n");
    format_commas((long long)llround(total), buf);
    printf("Total Budget: $%s\n", buf);

    for (size_t i = 0; i < nemp; i++) {
        free(emps[i].name);
        free(emps[i].dept);
    }
    free(emps);
    for (size_t i = 0; i < ndepts; i++)
        free(depts[i].name);
    free(depts);
    free(highest_name);

    return 0;
}

