            }
        }
        if (!d) {
            if (ndepts == capdepts) {
                capdepts = capdepts ? capdepts * 2 : 8;
                depts = realloc(depts, capdepts * sizeof *depts);
                if (!depts) {
                    fprintf(stderr, "out of memory\n");
                    return 1;
                }
            }
            d = &depts[ndepts++];
            d->name = xstrdup(f_dept);
            d->sum = 0.0;
            d->count = 0;
        }
        d->sum += sal;
        d->count++;
        total += sal;

        if (sal > highest_sal) {
            highest_sal = sal;
            if (highest_name)
                free(highest_name);
            highest_name = xstrdup(f_name);
        }

        /* keep employee record (dynamic array) */
        if (nemp == capemp) {
            capemp = capemp ? capemp * 2 : 16;
            emps = realloc(emps, capemp * sizeof *emps);
            if (!emps) {
                fprintf(stderr, "out of memory\n");
                return 1;
            }
        }
        emps[nemp].name = xstrdup(f_name);
        emps[nemp].dept = xstrdup(f_dept);
        emps[nemp].salary = sal;
        nemp++;
    }

    free(line);
    fclose(fp);

    qsort(depts, ndepts, sizeof *depts, cmp_dept);

    char buf[256];

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (size_t i = 0; i < ndepts; i++) {
        double avg = depts[i].sum / (double)depts[i].count;
        format_avg(avg, buf);
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    if (highest_name) {
        format_commas((long long)llround(highest_sal), buf);
        printf("Highest Paid: %s ($%s)\n", highest_name, buf);
    } else {
        printf("Highest Paid: N/A ($0)\n");
    }
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (size_t i = 0; i < ndepts; i++) {
        if (depts[i].count > 2)
            printf("  %s (%ld employees)\n", depts[i].name, depts[i].count);
    }
    printf("\n");
    format_commas((long long)llround(total), buf);
    printf("Total Budget: $%s\n", buf);

    for (size_t i = 0; i < nemp; i++) {
        free(emps[i].name);
        free(emps[i].dept);
    }
    free(emps);
    for (size_t i = 0; i < ndepts; i++)
        free(depts[i].name);
    free(depts);
    free(highest_name);

    return 0;
