use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

fn json_eq(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Null, Json::Null) => true,
        (Json::Bool(x), Json::Bool(y)) => x == y,
        (Json::Number(x), Json::Number(y)) => x == y,
        (Json::String(x), Json::String(y)) => x == y,
        (Json::Array(x), Json::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| json_eq(a, b))
        }
        (Json::Object(x), Json::Object(y)) => {
            x.len() == y.len()
                && x.iter().all(|(k, v)| y.get(k).map_or(false, |v2| json_eq(v, v2)))
        }
        _ => false,
    }
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser {
            chars: s.chars().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        self.parse_value()
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.expect("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.expect("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.expect("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect(&mut self, s: &str) {
        for c in s.chars() {
            assert_eq!(self.next(), Some(c));
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next();
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            assert_eq!(self.next(), Some(':'));
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}' in object"),
            }
        }
        Json::Object(map)
    }

    fn parse_array(&mut self) -> Json {
        self.next();
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            let value = self.parse_value();
            arr.push(value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.next(), Some('"'));
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('n') => s.push('\n'),
                    Some('r') => s.push('\r'),
                    Some('t') => s.push('\t'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next().unwrap();
                            code = code * 16 + c.to_digit(16).unwrap();
                        }
                        if (0xD800..0xDC00).contains(&code) {
                            assert_eq!(self.next(), Some('\\'));
                            assert_eq!(self.next(), Some('u'));
                            let mut low: u32 = 0;
                            for _ in 0..4 {
                                let c = self.next().unwrap();
                                low = low * 16 + c.to_digit(16).unwrap();
                            }
                            let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                            s.push(char::from_u32(cp).unwrap());
                        } else {
                            s.push(char::from_u32(code).unwrap());
                        }
                    }
                    _ => panic!("Invalid escape sequence"),
                },
                Some(c) => s.push(c),
                None => panic!("Unexpected end of string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.next();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                self.next();
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Number(s.parse::<f64>().unwrap())
    }
}

fn merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (k, v) in a_map {
                match b_map.get(k) {
                    Some(bv) => {
                        result.insert(k.clone(), merge(v, bv));
                    }
                    None => {
                        result.insert(k.clone(), v.clone());
                    }
                }
            }
            for (k, v) in b_map {
                if !a_map.contains_key(k) {
                    result.insert(k.clone(), v.clone());
                }
            }
            Json::Object(result)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut result: Vec<Json> = a_arr.clone();
            for item in b_arr {
                if !result.iter().any(|existing| json_eq(existing, item)) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        _ => b.clone(),
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => result.push_str(&format!("\\u{:04x}", c as u32)),
            c => result.push(c),
        }
    }
    result
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => {
            if n.fract() == 0.0 && n.abs() < 1e15 {
                format!("{}", *n as i64)
            } else {
                format!("{}", n)
            }
        }
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let items: Vec<String> = arr
                    .iter()
                    .map(|v| format!("{}{}", pad_inner, serialize(v, indent + 1)))
                    .collect();
                format!("[\n{}\n{}]", items.join(",\n"), pad)
            }
        }
        Json::Object(obj) => {
            if obj.is_empty() {
                "{}".to_string()
            } else {
                let items: Vec<String> = obj
                    .iter()
                    .map(|(k, v)| {
                        format!(
                            "{}\"{}\": {}",
                            pad_inner,
                            escape_string(k),
                            serialize(v, indent + 1)
                        )
                    })
                    .collect();
                format!("{{\n{}\n{}}}", items.join(",\n"), pad)
            }
        }
    }
}

fn main() {
    let path_a =
        "<tmp>";
    let path_b =
        "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let json_a = Parser::new(&content_a).parse();
    let json_b = Parser::new(&content_b).parse();

    let merged = merge(&json_a, &json_b);

    print!("{}", serialize(&merged, 0));
}

