import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<String[]>> extMap = new TreeMap<>();
        List<Path> files = new ArrayList<>();
        walkDir(root, files);

        for (Path file : files) {
            String relPath = root.relativize(file).toString().replace('\\', '/');
            String fileName = file.getFileName().toString();

            String ext;
            int lastDot = fileName.lastIndexOf('.');
            if (lastDot > 0) {
                ext = fileName.substring(lastDot);
            } else {
                ext = "(none)";
            }

            byte[] bytes = Files.readAllBytes(file);
            int chars = bytes.length;
            int lines = countLines(bytes);

            extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                  .add(new String[]{relPath, String.valueOf(lines), String.valueOf(chars)});
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        int totalFiles = 0;
        int totalLines = 0;
        int totalChars = 0;

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> filesList = entry.getValue();

            filesList.sort((a, b) -> a[0].compareTo(b[0]));

            int extLines = 0;
            int extChars = 0;
            for (String[] f : filesList) {
                extLines += Integer.parseInt(f[1]);
                extChars += Integer.parseInt(f[2]);
            }

            totalFiles += filesList.size();
            totalLines += extLines;
            totalChars += extChars;

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + filesList.size());
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);
            for (String[] f : filesList) {
                System.out.println("    " + f[0] + ": " + f[1] + " lines, " + f[2] + " chars");
            }
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static void walkDir(Path root, List<Path> files) throws IOException {
        if (!Files.isDirectory(root)) return;
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(root)) {
            for (Path entry : stream) {
                if (Files.isSymbolicLink(entry)) continue;
                if (Files.isDirectory(entry)) {
                    walkDir(entry, files);
                } else if (Files.isRegularFile(entry)) {
                    files.add(entry);
                }
            }
        }
    }

    static int countLines(byte[] bytes) {
        if (bytes.length == 0) return 0;
        int count = 0;
        for (byte b : bytes) {
            if (b == '\n') count++;
        }
        if (bytes[bytes.length - 1] != '\n') count++;
        return count;
    }
}

