        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) sb.append(' ');
        return sb.toString();
    }

    static String escapeString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    static void prettyPrintValue(Object value, int indent, StringBuilder sb) {
        if (value == null) {
            sb.append("null");
        } else if (value instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) value;
            if (map.isEmpty()) {
                sb.append("{}");
            } else {
                sb.append("{\n");
                List<String> keys = new ArrayList<>(map.keySet());
                Collections.sort(keys);
                for (int i = 0; i < keys.size(); i++) {
                    String key = keys.get(i);
                    sb.append(spaces(indent + 2));
                    sb.append("\"");
                    sb.append(escapeString(key));
                    sb.append("\": ");
                    prettyPrintValue(map.get(key), indent + 2, sb);
                    if (i < keys.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append(spaces(indent));
                sb.append("}");
            }
        } else if (value instanceof List) {
            List<Object> list = (List<Object>) value;
            if (list.isEmpty()) {
                sb.append("[]");
            } else {
                sb.append("[\n");
                for (int i = 0; i < list.size(); i++) {
                    sb.append(spaces(indent + 2));
                    prettyPrintValue(list.get(i), indent + 2, sb);
                    if (i < list.size() - 1) sb.append(",");
                    sb.append("\n");
                }
                sb.append(spaces(indent));
                sb.append("]");
            }
        } else if (value instanceof String) {
            sb.append("\"");
            sb.append(escapeString((String) value));
            sb.append("\"");
        } else if (value instanceof Boolean) {
            sb.append(value.toString());
        } else if (value instanceof Long) {
            sb.append(value.toString());
        } else if (value instanceof Double) {
            double d = (Double) value;
            if (d == Math.floor(d) && !Double.isInfinite(d) && !Double.isNaN(d) && Math.abs(d) < 1e15) {
                sb.append(d).append(".0");
            } else {
                sb.append(Double.toString(d));
            }
        }
    }

    public static void main(String[] args) throws Exception {
        String pathA = "<tmp>";
        String pathB = "<tmp>";

        String jsonA = new String(Files.readAllBytes(Paths.get(pathA)), "UTF-8");
        String jsonB = new String(Files.readAllBytes(Paths.get(pathB)), "UTF-8");

        Object objA = new JsonParser(jsonA).parse();
        Object objB = new JsonParser(jsonB).parse();

        Object merged = deepMerge(objA, objB);

        StringBuilder sb = new StringBuilder();
        prettyPrintValue(merged, 0, sb);
        System.out.println(sb.toString());
    }
