#include <string.h>

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) { pclose(fp); return NULL; }

    size_t total = 0;
    size_t n;
    while ((n = fread(buf + total, 1, cap - total - 1, fp)) > 0) {
        total += n;
        if (total + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); pclose(fp); return NULL; }
            buf = tmp;
        }
    }
    pclose(fp);
    buf[total] = '\0';

    /* strip trailing whitespace */
    while (total > 0) {
        char c = buf[total - 1];
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t')
            total--;
        else
            break;
    }
    buf[total] = '\0';

    return buf;
}

