fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    for (path, lines, chars) in files {
        let ext = get_extension(&path);
        groups.entry(ext).or_default().push((path, lines, chars));
    }

    for group in groups.values_mut() {
        group.sort_by(|a, b| a.0.cmp(&b.0));
    }

    let total_files: u64 = groups.values().map(|g| g.len() as u64).sum();
    let total_lines: u64 = groups.values().map(|g| g.iter().map(|f| f.1).sum::<u64>()).sum();
    let total_chars: u64 = groups.values().map(|g| g.iter().map(|f| f.2).sum::<u64>()).sum();

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, group) in &groups {
        println!("Extension: {}", ext);
        println!("  Files: {}", group.len());
        let lines: u64 = group.iter().map(|f| f.1).sum();
        let chars: u64 = group.iter().map(|f| f.2).sum();
        println!("  Total Lines: {}", lines);
        println!("  Total Characters: {}", chars);
        for (path, lines, chars) in group {
            println!("    {}: {} lines, {} chars", path, lines, chars);
        }
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn get_extension(path: &str) -> String {
    let filename = path.rsplit('/').next().unwrap_or(path);
    match filename.rfind('.') {
        Some(pos) if pos > 0 => filename[pos..].to_string(),
        _ => String::new(),
    }
}

