    visitedDirs.insert(dirPath)

    let fm = FileManager.default
    guard let contents = try? fm.contentsOfDirectory(atPath: dirPath) else { return }

    for name in contents {
        let fullPath = dirPath + "/" + name

        var isSymlink: ObjCBool = false
        fm.fileExists(atPath: fullPath, isSymbolicLink: &isSymlink)
        if isSymlink.boolValue { continue }

        var isDir: ObjCBool = false
        fm.fileExists(atPath: fullPath, isDirectory: &isDir)

        if isDir.boolValue {
