use std::fs;
use std::collections::{HashMap, BinaryHeap};
use std::cmp::Ordering;

#[derive(PartialEq)]
struct HeapItem {
    dist: f64,
    node: String,
}

impl Eq for HeapItem {}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        // Min-heap: smaller distance has higher priority (popped first)
        other.dist.partial_cmp(&self.dist)
            .unwrap_or(Ordering::Equal)
            .then_with(|| self.node.cmp(&other.node))
    }
}

fn parse_string_array(content: &str, key: &str) -> Vec<String> {
    let key_pattern = format!("\"{}\"", key);
    let key_pos = content.find(&key_pattern).unwrap();
    let bracket_pos = content[key_pos..].find('[').unwrap() + key_pos;
    let close_bracket = content[bracket_pos..].find(']').unwrap() + bracket_pos;
    let inner = &content[bracket_pos + 1..close_bracket];

    let mut result = Vec::new();
    let bytes = inner.as_bytes();
    let mut i = 0;
    while i < inner.len() {
        if bytes[i] == b'"' {
            let start = i + 1;
            let end = inner[start..].find('"').unwrap() + start;
            result.push(inner[start..end].to_string());
            i = end + 1;
        } else {
            i += 1;
        }
    }
    result
}

fn extract_string(obj: &str, key: &str) -> String {
    let pattern = format!("\"{}\"", key);
    let pos = obj.find(&pattern).unwrap();
    let after_key = &obj[pos + pattern.len()..];
    let colon_pos = after_key.find(':').unwrap();
    let after_colon = &after_key[colon_pos + 1..];
    let quote_pos = after_colon.find('"').unwrap();
    let after_quote = &after_colon[quote_pos + 1..];
    let end_quote = after_quote.find('"').unwrap();
    after_quote[..end_quote].to_string()
}

fn extract_number(obj: &str, key: &str) -> f64 {
    let pattern = format!("\"{}\"", key);
    let pos = obj.find(&pattern).unwrap();
    let after_key = &obj[pos + pattern.len()..];
    let colon_pos = after_key.find(':').unwrap();
    let after_colon = &after_key[colon_pos + 1..].trim();
    let mut end = 0;
    for (i, c) in after_colon.char_indices() {
        if c.is_ascii_digit() || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E' {
            end = i + c.len_utf8();
        } else {
            break;
        }
    }
    after_colon[..end].parse().unwrap()
}

fn parse_edges(content: &str) -> Vec<(String, String, f64)> {
    let key_pattern = "\"edges\"";
    let key_pos = content.find(key_pattern).unwrap();
    let bracket_pos = content[key_pos..].find('[').unwrap() + key_pos;

    let mut depth = 0;
    let mut close_bracket = bracket_pos;
    for (i, c) in content[bracket_pos..].char_indices() {
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
            if depth == 0 {
                close_bracket = bracket_pos + i;
                break;
            }
        }
    }

    let inner = &content[bracket_pos + 1..close_bracket];
    let mut edges = Vec::new();
    let bytes = inner.as_bytes();

    let mut i = 0;
    while i < inner.len() {
        if bytes[i] == b'{' {
            let mut obj_depth = 0;
            let mut obj_end = i;
            for (j, c) in inner[i..].char_indices() {
                if c == '{' {
                    obj_depth += 1;
