static void add_file(const char *relpath, long lines, long chars) {
    if (nfiles == capfiles) {
        capfiles = capfiles ? capfiles * 2 : 128;
        files = realloc(files, (size_t)capfiles * sizeof(FileInfo));
        if (!files) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    files[nfiles].relpath = strdup(relpath);
    if (!files[nfiles].relpath) { fprintf(stderr, "OOM\n"); exit(1); }

    const char *dot = strrchr(relpath, '.');
    const char *slash = strrchr(relpath, '/');
    if (dot && (!slash || dot > slash)) {
        files[nfiles].ext = strdup(dot);
    } else {
        files[nfiles].ext = strdup("");
    }
    if (!files[nfiles].ext) { fprintf(stderr, "OOM\n"); exit(1); }

    files[nfiles].lines = lines;
    files[nfiles].chars = chars;
    nfiles++;
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) { *lines = 0; *chars = 0; return; }

    *lines = 0;
    *chars = 0;
    size_t bufsz = 65536;
    char *buf = malloc(bufsz);
    if (!buf) { fclose(f); exit(1); }

    int any = 0;
    int ended_with_newline = 0;
    size_t n;

    while ((n = fread(buf, 1, bufsz, f)) > 0) {
        for (size_t i = 0; i < n; i++) {
            (*chars)++;
            any = 1;
            if (buf[i] == '\n') {
                (*lines)++;
                ended_with_newline = 1;
            } else {
                ended_with_newline = 0;
            }
        }
    }
    if (any && !ended_with_newline) {
        (*lines)++;
    }

    free(buf);
    fclose(f);
}

static void walk(const char *dirpath, const char *relprefix) {
    DIR *d = opendir(dirpath);
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        size_t fullsz = strlen(dirpath) + 1 + strlen(ent->d_name) + 1;
        char *fullpath = malloc(fullsz);
        if (!fullpath) { closedir(d); exit(1); }
        snprintf(fullpath, fullsz, "%s/%s", dirpath, ent->d_name);

        char *relpath;
        if (relprefix[0] == '\0') {
            relpath = strdup(ent->d_name);
        } else {
            size_t relsz = strlen(relprefix) + 1 + strlen(ent->d_name) + 1;
            relpath = malloc(relsz);
            if (!relpath) { free(fullpath); closedir(d); exit(1); }
            snprintf(relpath, relsz, "%s/%s", relprefix, ent->d_name);
        }
        if (!relpath) { free(fullpath); closedir(d); exit(1); }

        struct stat st;
        if (lstat(fullpath, &st) == 0) {
            if (S_ISREG(st.st_mode)) {
                long lines, chars;
                count_file(fullpath, &lines, &chars);
                add_file(relpath, lines, chars);
            } else if (S_ISDIR(st.st_mode)) {
                walk(fullpath, relpath);
            }
        }

        free(fullpath);
        free(relpath);
    }
    closedir(d);
}

