static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = rd;
    return buf;
}

static int jval_equal(jval *a, jval *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case J_NULL: return 1;
        case J_BOOL: return a->bool_val == b->bool_val;
        case J_NUM: return a->num_val == b->num_val;
        case J_STR: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case J_ARR: {
            if (a->arr_len != b->arr_len) return 0;
            for (int i = 0; i < a->arr_len; i++) {
