static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = rd;
    return buf;
}

static int jval_equal(jval *a, jval *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case J_NULL: return 1;
        case J_BOOL: return a->bool_val == b->bool_val;
        case J_NUM: return a->num_val == b->num_val;
        case J_STR: return a->str_val && b->str_val && strcmp(a->str_val, b->str_val) == 0;
        case J_ARR: {
            if (a->arr_len != b->arr_len) return 0;
            for (int i = 0; i < a->arr_len; i++) {
                if (!jval_equal(a->arr_items[i], b->arr_items[i])) return 0;
            }
            return 1;
        }
        case J_OBJ: {
            if (a->obj_len != b->obj_len) return 0;
            for (int i = 0; i < a->obj_len; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_len; j++) {
                    if (strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                        if (!jval_equal(a->obj_vals[i], b->obj_vals[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

static int arr_contains(jval *arr, jval *item) {
    for (int i = 0; i < arr->arr_len; i++) {
        if (jval_equal(arr->arr_items[i], item)) return 1;
    }
    return 0;
}

static jval *merge(jval *a, jval *b) {
    if (a->type == J_OBJ && b->type == J_OBJ) {
        jval *result = jval_new(J_OBJ);
        result->obj_cap = a->obj_len + b->obj_len + 4;
        result->obj_keys = (char **)malloc(sizeof(char *) * result->obj_cap);
        result->obj_vals = (jval **)malloc(sizeof(jval *) * result->obj_cap);
        /* Add all from A */
        for (int i = 0; i < a->obj_len; i++) {
            result->obj_keys[result->obj_len] = strdup(a->obj_keys[i]);
            result->obj_vals[result->obj_len] = a->obj_vals[i];
            result->obj_len++;
        }
        /* Merge B into result */
        for (int i = 0; i < b->obj_len; i++) {
            int found = -1;
            for (int j = 0; j < result->obj_len; j++) {
                if (strcmp(result->obj_keys[j], b->obj_keys[i]) == 0) {
                    found = j;
                    break;
                }
            }
            if (found >= 0) {
                result->obj_vals[found] = merge(result->obj_vals[found], b->obj_vals[i]);
            } else {
                if (result->obj_len >= result->obj_cap) {
                    result->obj_cap *= 2;
                    result->obj_keys = (char **)realloc(result->obj_keys, sizeof(char *) * result->obj_cap);
                    result->obj_vals = (jval **)realloc(result->obj_vals, sizeof(jval *) * result->obj_cap);
                }
                result->obj_keys[result->obj_len] = strdup(b->obj_keys[i]);
                result->obj_vals[result->obj_len] = b->obj_vals[i];
                result->obj_len++;
            }
        }
        return result;
    }
    if (a->type == J_ARR && b->type == J_ARR) {
        jval *result = jval_new(J_ARR);
        result->arr_cap = a->arr_len + b->arr_len + 4;
        result->arr_items = (jval **)malloc(sizeof(jval *) * result->arr_cap);
        /* Add all from A */
        for (int i = 0; i < a->arr_len; i++) {
            result->arr_items[result->arr_len++] = a->arr_items[i];
        }
        /* Add new items from B (not already present) */
        for (int i = 0; i < b->arr_len; i++) {
            if (!arr_contains(result, b->arr_items[i])) {
                result->arr_items[result->arr_len++] = b->arr_items[i];
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return b;
}

static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') fputs("\\\"", stdout);
        else if (c == '\\') fputs("\\\\", stdout);
        else if (c == '\n') fputs("\\n", stdout);
        else if (c == '\r') fputs("\\r", stdout);
        else if (c == '\t') fputs("\\t", stdout);
        else if (c == '\b') fputs("\\b", stdout);
        else if (c == '\f') fputs("\\f", stdout);
        else if (c < 0x20) printf("\\u%04x", c);
        else fputc(c, stdout);
    }
    fputc('"', stdout);
}

static void print_indent(int level) {
    for (int i = 0; i < level; i) fputs("  ", stdout);
}

static void print_json(jval *v, int indent) {
    if (!v) { fputs("null", stdout); return; }
    switch (v->type) {
        case J_NULL:
            fputs("null", stdout);
            break;
        case J_BOOL:
            fputs(v->bool_val ? "true" : "false", stdout);
            break;
        case J_NUM:
            if (v->num_str) {
                fputs(v->num_str, stdout);
            } else {
                if (v->num_val == (double)(long long)v->num_val && fabs(v->num_val) < 9.2e18) {
                    printf("%lld", (long long)v->num_val);
                } else {
                    printf("%.15g", v->num_val);
                }
            }
            break;
        case J_STR:
            print_string_escaped(v->str_val);
            break;
        case J_ARR:
            if (v->arr_len == 0) {
                fputs("[]", stdout);
            } else {
                fputs("[\n", stdout);
                for (int i = 0; i < v->arr_len; i++) {
                    print_indent(indent + 1);
                    print_json(v->arr_items[i], indent + 1);
                    if (i < v->arr_len - 1) fputc(',', stdout);
                    fputc('\n', stdout);
                }
                print_indent(indent);
                fputc(']', stdout);
            }
            break;
        case J_OBJ:
            if (v->obj_len == 0) {
                fputs("{}", stdout);
            } else {
                /* Sort keys alphabetically */
                int n = v->obj_len;
                char **keys = (char **)malloc(sizeof(char *) * n);
                jval **vals = (jval **)malloc(sizeof(jval *) * n);
                for (int i = 0; i < n; i++) {
                    keys[i] = v->obj_keys[i];
                    vals[i] = v->obj_vals[i];
                }
                /* Simple insertion sort for keys */
                for (int i = 1; i < n; i++) {
                    char *kk = keys[i];
                    jval *vv = vals[i];
                    int j = i - 1;
                    while (j >= 0 && strcmp(keys[j], kk) > 0) {
                        keys[j+1] = keys[j];
                        vals[j+1] = vals[j];
                        j--;
                    }
                    keys[j+1] = kk;
                    vals[j+1] = vv;
                }
                fputs("{\n", stdout);
                for (int i = 0; i < n; i++) {
                    print_indent(indent + 1);
                    print_string_escaped(keys[i]);
                    fputs(": ", stdout);
                    print_json(vals[i], indent + 1);
                    if (i < n - 1) fputc(',', stdout);
                    fputc('\n', stdout);
                }
                print_indent(indent);
                fputc('}', stdout);
                free(keys);
                free(vals);
            }
            break;
    }
}

