    int *used;
    int cap;
    int count;
} str_hash;

static unsigned int djb2(const char *s) {
    unsigned int h = 5381;
    while (*s) { h = ((h << 5) + h) + (unsigned char)*s; s++; }
    return h;
}

static void hash_init(str_hash *h, int cap) {
    h->cap = cap;
    h->count = 0;
    h->entries = (char **)calloc((size_t)cap, sizeof(char *));
    h->used = (int *)calloc((size_t)cap, sizeof(int));
}

static void hash_free(str_hash *h) {
    for (int i = 0; i < h->cap; i++)
        if (h->used[i]) free(h->entries[i]);
    free(h->entries);
    free(h->used);
}

/* Returns 1 if newly inserted, 0 if already present */
static int hash_insert(str_hash *h, const char *s) {
    unsigned int idx = djb2(s) % (unsigned int)h->cap;
    while (h->used[idx]) {
        if (strcmp(h->entries[idx], s) == 0) return 0;
        idx = (idx + 1) % (unsigned int)h->cap;
    }
    h->used[idx] = 1;
    h->entries[idx] = strdup(s);
    h->count++;
    return 1;
}

