        case J_ARR:
            if (v->arr_len == 0) {
                fputs("[]", stdout);
            } else {
                fputs("[\n", stdout);
                for (int i = 0; i < v->arr_len; i++) {
                    print_indent(indent + 1);
                    print_json(v->arr_items[i], indent + 1);
                    if (i < v->arr_len - 1) fputc(',', stdout);
                    fputc('\n', stdout);
                }
