        if (!key) break;
        skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != ':') { free(key->str_val); free(key); break; }
        p->pos++;
        skip_ws(p);
        jval *val = parse_value(p);
        if (!val) { free(key->str_val); free(key); break; }
        if (v->obj_len >= v->obj_cap) {
            v->obj_cap *= 2;
            v->obj_keys = (char **)realloc(v->obj_keys, sizeof(char *) * v->obj_cap);
            v->obj_vals = (jval **)realloc(v->obj_vals, sizeof(jval *) * v->obj_cap);
        }
        v->obj_keys[v->obj_len] = key->str_val;
        v->obj_vals[v->obj_len] = val;
        v->obj_len++;
        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        else if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; break; }
        else break;
    }
    return v;
}

static jval *parse_array(parser *p) {
    p->pos++;
    jval *v = jval_new(J_ARR);
    v->arr_cap = 16;
    v->arr_items = (jval **)malloc(sizeof(jval *) * v->arr_cap);
    skip_ws(p);
    if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
    while (p->pos < p->len) {
        skip_ws(p);
        jval *item = parse_value(p);
        if (!item) break;
        if (v->arr_len >= v->arr_cap) {
            v->arr_cap *= 2;
            v->arr_items = (jval **)realloc(v->arr_items, sizeof(jval *) * v->arr_cap);
        }
        v->arr_items[v->arr_len++] = item;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
        else if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; break; }
        else break;
    }
    return v;
}

static jval *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->s[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') return parse_string(p);
    if (c == '-' || (c >= '0' && c <= '9')) return parse_number(p);
    if (c == 't' && p->len - p->pos >= 4 && memcmp(p->s + p->pos, "true", 4) == 0) {
        p->pos += 4;
        jval *v = jval_new(J_BOOL); v->bool_val = 1; return v;
    }
    if (c == 'f' && p->len - p->pos >= 5 && memcmp(p->s + p->pos, "false", 5) == 0) {
        p->pos += 5;
        jval *v = jval_new(J_BOOL); v->bool_val = 0; return v;
    }
    if (c == 'n' && p->len - p->pos >= 4 && memcmp(p->s + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return jval_new(J_NULL);
    }
    return NULL;
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = rd;
    return buf;
}

/* Hash set for string deduplication in array merge */
typedef struct {
    char **entries;
    int *used;
    int cap;
    int count;
} str_hash;

static unsigned int djb2(const char *s) {
    unsigned int h = 5381;
    while (*s) { h = ((h << 5) + h) + (unsigned char)*s; s++; }
    return h;
}

static void hash_init(str_hash *h, int cap) {
    h->cap = cap;
    h->count = 0;
    h->entries = (char **)calloc((size_t)cap, sizeof(char *));
    h->used = (int *)calloc((size_t)cap, sizeof(int));
}

static void hash_free(str_hash *h) {
    for (int i = 0; i < h->cap; i++)
        if (h->used[i]) free(h->entries[i]);
    free(h->entries);
    free(h->used);
}

/* Returns 1 if newly inserted, 0 if already present */
static int hash_insert(str_hash *h, const char *s) {
    unsigned int idx = djb2(s) % (unsigned int)h->cap;
    while (h->used[idx]) {
        if (strcmp(h->entries[idx], s) == 0) return 0;
        idx = (idx + 1) % (unsigned int)h->cap;
    }
    h->used[idx] = 1;
    h->entries[idx] = strdup(s);
    h->count++;
    return 1;
}

/* Serialize a jval to a canonical compact JSON string (for hashing) */
static void serialize_to_buf(jval *v, char **buf, int *len, int *cap) {
    #define GROW() do { *cap = *cap * 2 + 64; *buf = (char *)realloc(*buf, *cap); } while(0)
    if (!v) {
        if (*len + 4 >= *cap) GROW();
        memcpy(*buf + *len, "null", 5);
        *len += 4;
        return;
    }
    switch (v->type) {
        case J_NULL:
            if (*len + 4 >= *cap) GROW();
            memcpy(*buf + *len, "null", 5); *len += 4; break;
        case J_BOOL:
            if (*len + 5 >= *cap) GROW();
            if (v->bool_val) { memcpy(*buf + *len, "true", 5); *len += 4; }
            else { memcpy(*buf + *len, "false", 6); *len += 5; }
            break;
        case J_NUM:
            if (v->num_str) {
                int slen = (int)strlen(v->num_str);
                if (*len + slen + 1 >= *cap) GROW();
                memcpy(*buf + *len, v->num_str, slen); *len += slen;
            } else {
                char tmp[32];
                int slen;
                if (v->num_val == (double)(long long)v->num_val && fabs(v->num_val) < 9.2e18)
                    slen = snprintf(tmp, sizeof(tmp), "%lld", (long long)v->num_val);
                else
                    slen = snprintf(tmp, sizeof(tmp), "%.15g", v->num_val);
                if (*len + slen + 1 >= *cap) GROW();
                memcpy(*buf + *len, tmp, slen); *len += slen;
            }
            break;
        case J_STR:
            if (!v->str_val) { if (*len + 2 >= *cap) GROW(); memcpy(*buf + *len, "\"\"", 3); *len += 2; break; }
            /* Serialize with escaping */
            if (*len + 2 >= *cap) GROW();
            (*buf)[(*len)++] = '"';
            for (const char *p = v->str_val; *p; p++) {
                unsigned char c = (unsigned char)*p;
                if (c == '"' || c == '\\') {
                    if (*len + 2 >= *cap) GROW();
                    (*buf)[(*len)++] = '\\';
                    (*buf)[(*len)++] = (char)c;
                } else if (c < 0x20) {
                    if (*len + 6 >= *cap) GROW();
                    sprintf(*buf + *len, "\\u%04x", c);
                    *len += 6;
                } else {
                    if (*len + 1 >= *cap) GROW();
                    (*buf)[(*len)++] = (char)c;
                }
            }
            if (*len + 1 >= *cap) GROW();
            (*buf)[(*len)++] = '"';
            break;
        case J_ARR:
            if (*len + 1 >= *cap) GROW();
            (*buf)[(*len)++] = '[';
            for (int i = 0; i < v->arr_len; i++) {
                if (i > 0) { if (*len + 1 >= *cap) GROW(); (*buf)[(*len)++] = ','; }
                serialize_to_buf(v->arr_items[i], buf, len, cap);
            }
            if (*len + 1 >= *cap) GROW();
            (*buf)[(*len)++] = ']';
            break;
        case J_OBJ: {
            if (*len + 1 >= *cap) GROW();
            (*buf)[(*len)++] = '{';
            /* Sort keys for canonical form */
            int n = v->obj_len;
            if (n > 0) {
                char **ks = (char **)malloc(sizeof(char *) * n);
                jval **vs = (jval **)malloc(sizeof(jval *) * n);
                for (int i = 0; i < n; i++) { ks[i] = v->obj_keys[i]; vs[i] = v->obj_vals[i]; }
                for (int i = 1; i < n; i++) {
                    char *kk = ks[i]; jval *vv = vs[i];
                    int j = i - 1;
                    while (j >= 0 && strcmp(ks[j], kk) > 0) { ks[j+1]=ks[j]; vs[j+1]=vs[j]; j--; }
                    ks[j+1]=kk; vs[j+1]=vv;
                }
                for (int i = 0; i < n; i++) {
                    if (i > 0) { if (*len + 1 >= *cap) GROW(); (*buf)[(*len)++] = ','; }
                    /* key as string */
                    if (*len + 2 >= *cap) GROW();
                    (*buf)[(*len)++] = '"';
                    for (const char *p = ks[i]; *p; p++) {
                        unsigned char c = (unsigned char)*p;
                        if (c == '"' || c == '\\') { if (*len + 2 >= *cap) GROW(); (*buf)[(*len)++]='\\'; (*buf)[(*len)++]=(char)c; }
                        else if (c < 0x20) { if (*len + 6 >= *cap) GROW(); sprintf(*buf+*len,"\\u%04x",c); *len+=6; }
                        else { if (*len + 1 >= *cap) GROW(); (*buf)[(*len)++]=(char)c; }
                    }
                    if (*len + 1 >= *cap) GROW();
                    (*buf)[(*len)++] = '"';
                    if (*len + 1 >= *cap) GROW();
                    (*buf)[(*len)++] = ':';
                    serialize_to_buf(vs[i], buf, len, cap);
                }
                free(ks); free(vs);
            }
            if (*len + 1 >= *cap) GROW();
            (*buf)[(*len)++] = '}';
            break;
        }
    }
    #undef GROW
}

static jval *merge(jval *a, jval *b) {
    if (a->type == J_OBJ && b->type == J_OBJ) {
        jval *result = jval_new(J_OBJ);
        result->obj_cap = a->obj_len + b->obj_len + 4;
        result->obj_keys = (char **)malloc(sizeof(char *) * result->obj_cap);
        result->obj_vals = (jval **)malloc(sizeof(jval *) * result->obj_cap);
        for (int i = 0; i < a->obj_len; i++) {
            result->obj_keys[result->obj_len] = strdup(a->obj_keys[i]);
            result->obj_vals[result->obj_len] = a->obj_vals[i];
            result->obj_len++;
        }
        for (int i = 0; i < b->obj_len; i++) {
            int found = -1;
            for (int j = 0; j < result->obj_len; j++) {
                if (strcmp(result->obj_keys[j], b->obj_keys[i]) == 0) { found = j; break; }
            }
            if (found >= 0) {
                result->obj_vals[found] = merge(result->obj_vals[found], b->obj_vals[i]);
            } else {
                if (result->obj_len >= result->obj_cap) {
                    result->obj_cap *= 2;
                    result->obj_keys = (char **)realloc(result->obj_keys, sizeof(char *) * result->obj_cap);
                    result->obj_vals = (jval **)realloc(result->obj_vals, sizeof(jval *) * result->obj_cap);
                }
                result->obj_keys[result->obj_len] = strdup(b->obj_keys[i]);
                result->obj_vals[result->obj_len] = b->obj_vals[i];
                result->obj_len++;
            }
        }
        return result;
    }
    if (a->type == J_ARR && b->type == J_ARR) {
        jval *result = jval_new(J_ARR);
        result->arr_cap = a->arr_len + b->arr_len + 4;
        result->arr_items = (jval **)malloc(sizeof(jval *) * result->arr_cap);
        for (int i = 0; i < a->arr_len; i++) {
            result->arr_items[result->arr_len++] = a->arr_items[i];
        }
        /* Use hash set for dedup of B items */
        int hcap = (a->arr_len + b->arr_len) * 2 + 16;
        if (hcap < 64) hcap = 64;
        str_hash hs;
        hash_init(&hs, hcap);
        /* Add all A items to hash set */
        int scap = 256;
        char *sbuf = (char *)malloc(scap);
        for (int i = 0; i < a->arr_len; i++) {
            int slen = 0;
            serialize_to_buf(a->arr_items[i], &sbuf, &slen, &scap);
            sbuf[slen] = '\0';
            hash_insert(&hs, sbuf);
        }
        /* Add B items not already present */
        for (int i = 0; i < b->arr_len; i++) {
            int slen = 0;
            serialize_to_buf(b->arr_items[i], &sbuf, &slen, &scap);
            sbuf[slen] = '\0';
            if (hash_insert(&hs, sbuf)) {
                if (result->arr_len >= result->arr_cap) {
                    result->arr_cap *= 2;
                    result->arr_items = (jval **)realloc(result->arr_items, sizeof(jval *) * result->arr_cap);
                }
                result->arr_items[result->arr_len++] = b->arr_items[i];
            }
        }
        free(sbuf);
        hash_free(&hs);
        return result;
    }
    return b;
}

static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') fputs("\\\"", stdout);
        else if (c == '\\') fputs("\\\\", stdout);
        else if (c == '\n') fputs("\\n", stdout);
        else if (c == '\r') fputs("\\r", stdout);
        else if (c == '\t') fputs("\\t", stdout);
        else if (c == '\b') fputs("\\b", stdout);
        else if (c == '\f') fputs("\\f", stdout);
        else if (c < 0x20) printf("\\u%04x", c);
        else fputc(c, stdout);
    }
    fputc('"', stdout);
}

static void print_indent(int level) {
    for (int i = 0; i < level; i++) fputs("  ", stdout);
}

static int cmp_keys(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static void print_json(jval *v, int indent) {
    if (!v) { fputs("null", stdout); return; }
    switch (v->type) {
        case J_NULL:
            fputs("null", stdout);
            break;
        case J_BOOL:
            fputs(v->bool_val ? "true" : "false", stdout);
            break;
        case J_NUM:
            if (v->num_str) {
                fputs(v->num_str, stdout);
            } else {
                if (v->num_val == (double)(long long)v->num_val && fabs(v->num_val) < 9.2e18) {
                    printf("%lld", (long long)v->num_val);
                } else {
                    printf("%.15g", v->num_val);
                }
            }
            break;
        case J_STR:
            print_string_escaped(v->str_val);
            break;
        case J_ARR:
            if (v->arr_len == 0) {
                fputs("[]", stdout);
            } else {
                fputs("[\n", stdout);
                for (int i = 0; i < v->arr_len; i++) {
                    print_indent(indent + 1);
                    print_json(v->arr_items[i], indent + 1);
                    if (i < v->arr_len - 1) fputc(',', stdout);
                    fputc('\n', stdout);
                }
                print_indent(indent);
                fputc(']', stdout);
            }
            break;
        case J_OBJ:
            if (v->obj_len == 0) {
                fputs("{}", stdout);
            } else {
                int n = v->obj_len;
                char **keys = (char **)malloc(sizeof(char *) * n);
                jval **vals = (jval **)malloc(sizeof(jval *) * n);
                for (int i = 0; i < n; i++) { keys[i] = v->obj_keys[i]; vals[i] = v->obj_vals[i]; }
                qsort(keys, n, sizeof(char *), cmp_keys);
                /* Reorder vals to match sorted keys */
                /* Actually we need to sort both together. Let's use a struct. */
                free(keys); free(vals);
                /* Use a simple approach: sort indices */
                int *idx = (int *)malloc(sizeof(int) * n);
                for (int i = 0; i < n; i++) idx[i] = i;
                /* Sort by key using insertion sort on indices (n is small for config files) */
                for (int i = 1; i < n; i++) {
                    int ki = idx[i];
                    int j = i - 1;
                    while (j >= 0 && strcmp(v->obj_keys[idx[j]], v->obj_keys[ki]) > 0) {
                        idx[j+1] = idx[j]; j--;
                    }
                    idx[j+1] = ki;
                }
                fputs("{\n", stdout);
                for (int i = 0; i < n; i++) {
                    int k = idx[i];
                    print_indent(indent + 1);
                    print_string_escaped(v->obj_keys[k]);
                    fputs(": ", stdout);
                    print_json(v->obj_vals[k], indent + 1);
                    if (i < n - 1) fputc(',', stdout);
                    fputc('\n', stdout);
                }
                print_indent(indent);
                fputc('}', stdout);
                free(idx);
            }
            break;
    }
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    /* Use a large output buffer for speed */
    static char outbuf[1 << 20];
    setvbuf(stdout, outbuf, _IOFBF, sizeof(outbuf));

    size_t len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);
    if (!buf_a || !buf_b) {
        fprintf(stderr, "Error: could not read input files\n");
        return 1;
    }

    parser pa = { buf_a, 0, len_a };
    parser pb = { buf_b, 0, len_b };

    jval *a = parse_value(&pa);
    jval *b = parse_value(&pb);
    if (!a || !b) {
        fprintf(stderr, "Error: JSON parse failed\n");
        return 1;
    }

    jval *merged = merge(a, b);
    print_json(merged, 0);
    fputc('\n', stdout);
    fflush(stdout);

    free(buf_a);
    free(buf_b);
    return 0;
}
